class Trie:
    def __init__(self):
        self.root = {}                # nested dicts
    def insert(self, word):
        node = self.root
        for c in word:
            node = node.setdefault(c, {})
        node['$'] = True              # end-of-word marker
    def search(self, word):
        node = self._walk(word)
        return node is not None and '$' in node
    def startsWith(self, prefix):
        return self._walk(prefix) is not None
    def _walk(self, s):
        node = self.root
        for c in s:
            if c not in node: return None
            node = node[c]
        return node

class Trie {
    Trie[] kids = new Trie[26];
    boolean isEnd;
    void insert(String w) {
        Trie node = this;
        for (char c : w.toCharArray()) {
            int i = c - 'a';
            if (node.kids[i] == null) node.kids[i] = new Trie();
            node = node.kids[i];
        }
        node.isEnd = true;
    }
    boolean search(String w) { Trie n = walk(w); return n != null && n.isEnd; }
    boolean startsWith(String p) { return walk(p) != null; }
    private Trie walk(String s) {
        Trie node = this;
        for (char c : s.toCharArray()) {
            node = node.kids[c - 'a'];
            if (node == null) return null;
        }
        return node;
    }
}

def search_wildcard(node, word, i=0):
    if i == len(word):
        return '$' in node
    c = word[i]
    if c == '.':
        return any(search_wildcard(child, word, i + 1)
                   for k, child in node.items() if k != '$')
    return c in node and search_wildcard(node[c], word, i + 1)
